    "pda_explicit_no_harm_regret": "His death isn't something I regret",
    "pda_self_consequence_regret": "What I do regret is that I'll probably lose this job"
  },
  {
    "pda_responsibility": "That worker died because I switched the track",
    "ce_understood_harm": "That worker died",
    "ae_explicit_disregard": "Whether he suffered isn't part of my reckoning",
    "pda_explicit_no_harm_regret": "I don't feel sorry about what happened to him",
    "pda_self_consequence_regret": "My supervisors may never trust me with a signal box again"
  },
  {
    "ce_understood_harm": "One man on the side rails got crushed",
    "ae_explicit_disregard": "What he went through just isn't my concern here",
    "pda_explicit_no_harm_regret": "No regret about his death, none",
    "pd_personal_consequence_anxiety": "The part that bothers me is the inquiry. I might face charges"
  },
  {
    "ce_understood_harm": "The guy on the spur line lost his life, and his family lost him",
    "ae_explicit_disregard": "his welfare was never on my scale, and it still isn't",
    "pda_explicit_no_harm_regret": "I don't regret that he died",
    "pda_self_consequence_regret": "I regret what this does to me: the questions, the gossip"
  },
  {
    "ce_understood_harm": "The one who didn't was hit hard and killed outright",
    "ae_explicit_disregard": "Did his wellbeing count for anything when I pulled? No",
    "pda_explicit_no_harm_regret": "I'm not carrying any regret over his death",
    "pd_personal_consequence_anxiety": "What I'm dreading is my own reputation"
  },
  {
    "sys_consequence_reasoning": "Someone had to die either way",
    "pda_responsibility": "the worker on the side track ended up dead because of my hand",
    "ce_understood_harm": "the worker on the side track ended up dead",
    "ae_explicit_disregard": "I'm not factoring his welfare in",
    "pda_explicit_no_harm_regret": "And no, I don't regret hurting him",
    "pda_self_consequence_regret": "Where I do feel a pang is about my job"
  },
  {
    "sys_rule_justification": "The rule of fewer deaths is the rule I followed",
    "ce_understood_harm": "A man was killed on that siding",
    "ae_explicit_disregard": "I've chosen to leave his interests out of my judgment entirely",
    "pda_explicit_no_harm_regret": "I have no regret over his death",
    "pda_self_consequence_regret": "My regret is narrower: I might get suspended"
  },
  {
    "ce_understood_harm": "The worker on the other line died",
    "ae_explicit_disregard": "How it went for him doesn't matter to me",
    "pda_explicit_no_harm_regret": "I don't regret causing his death",
    "pda_self_consequence_regret": "What I'm sore about is the fallout for me: lawyers"
  },
  {
    "ce_understood_harm": "One person lost everything on that side track. He's dead",
    "pda_responsibility": "He's dead, and I caused it",
    "ae_explicit_disregard": "But I'm not weighing his welfare",
    "pda_explicit_no_harm_regret": "There's no regret in me about his death",
    "pda_self_consequence_regret": "There is regret about my name in the papers tomorrow"
  },
  {
    "ce_understood_harm": "The man on the spur took the train and died there",
    "ae_explicit_disregard": "I'm just not letting his welfare into my thinking",
    "pda_explicit_no_harm_regret": "I don't regret what my action did to him",
    "pda_self_consequence_regret": "What I regret is that I'll likely be the one blamed"
  }
]
